def reducer(state, aksi):
    """Fungsi murni: state lama + aksi -> state baru, tanpa mengubah yang lama."""
    if aksi["jenis"] == "tambah":
        isi = dict(state["isi"])
        isi[aksi["barang"]] = isi.get(aksi["barang"], 0) + 1
        return {**state, "isi": isi}
    if aksi["jenis"] == "hapus":
        isi = {k: v for k, v in state["isi"].items() if k != aksi["barang"]}
        return {**state, "isi": isi}
    return state


def tampilkan(state):
    print("keranjang:", state["isi"])


