import sys
from collections import OrderedDict


class Breaker:
    def __init__(self, ambang, tunggu):
        self.ambang, self.tunggu = ambang, tunggu
        self.keadaan, self.gagal, self.dibuka = "CLOSED", 0, 0

    def boleh(self, t):
        return self.keadaan != "OPEN" or t - self.dibuka >= self.tunggu

    def catat(self, t, sukses):
        """Catat hasil panggilan; kembalikan "OPEN"/"CLOSED" kalau keadaan berubah."""
        uji = self.keadaan == "OPEN"     # boleh() sudah mengizinkan: panggilan uji
        if sukses:
            self.gagal = 0
            if uji:
                self.keadaan = "CLOSED"
                return "CLOSED"
            return ""
        self.gagal += 1
        if uji or self.gagal >= self.ambang:
            self.keadaan, self.dibuka = "OPEN", t
            return "OPEN"
        return ""


baris = [b for b in sys.stdin.read().split("\n") if b.strip()]
konfig, kejadian = {}, []
rusak = []
for b in baris:
    kata = b.split()
    if kata[0] == "rusak":
        rusak.append((kata[1], int(kata[2]), int(kata[3])))
    elif kata[0].isdigit():
        kejadian.append((int(kata[0]), kata[1], kata[2], kata[3]))
    else:
        konfig[kata[0]] = kata[1:]

kapasitas_cache = int(konfig["cache"][0])
isi_ember, laju = map(int, konfig["token"])
backend = konfig["backend"]
ambang, tunggu = map(int, konfig["breaker"])

cache = OrderedDict()
ember = {}
breaker = {n: Breaker(ambang, tunggu) for n in backend}
panggilan = {n: 0 for n in backend}
giliran = 0
hitung = {"200": 0, "429": 0, "502": 0, "503": 0, "cache": 0}


def pilih(t, kecuali):
    """Round-robin: backend berikutnya yang breaker-nya mengizinkan."""
    global giliran
    for k in range(len(backend)):
        i = (giliran + k) % len(backend)
        nama = backend[i]
        if nama != kecuali and breaker[nama].boleh(t):
            giliran = (i + 1) % len(backend)
            return nama
    return None


def panggil(t, nama):
    panggilan[nama] += 1
    sukses = not any(n == nama and a <= t < z for n, a, z in rusak)
    ubah = breaker[nama].catat(t, sukses)
    return sukses, ubah


for t, klien, metode, path in kejadian:
    awal = f"t={t} {klien} {metode} {path}:"
    sisa, terakhir = ember.get(klien, (isi_ember, t))
    sisa = min(isi_ember, sisa + (t - terakhir) * laju)
    if sisa < 1:
        ember[klien] = (sisa, t)
        hitung["429"] += 1
        print(awal, "429 limiter")
        continue
    ember[klien] = (sisa - 1, t)

    if metode == "GET" and path in cache:
        cache.move_to_end(path)
        hitung["cache"] += 1
        hitung["200"] += 1
        print(awal, "200 cache")
        continue
    if metode == "POST":
        cache.pop(path, None)

    catatan = []
